/* ============================================================
   Gralha-azul: tudo sobre este animal fica nesta pasta.
   Seções: 1) dados e card · 2) ícone · 3) modelo 3D · 4) comportamento

   Modelo 3D realista: "Azure-hooded Jay - Cyanolyca cuculatta"
   por MooreLab (https://sketchfab.com/MooreLab), licença CC-BY-4.0
   https://sketchfab.com/3d-models/azure-hooded-jay-cyanolyca-cuculatta-56e83b618a8444efb694d367c5a6a283
   (malha reduzida e textura comprimida para rodar com muitas aves na cena)
   ============================================================ */

/* --- Dados do modelo 3D embutidos (NÃO EDITAR; sem arquivos externos, funciona abrindo direto o index.html) --- */
const GRALHA_MESH = {"n":12771,"pos":"","nrm":"","uv":"","idx":"","minY":-0.08741187571782655,"maxY":0.08733451466254069,"tex":"data:image/jpeg;base64,"};

registerAnimal('gralha', {

  /* 1) DADOS: card informativo, quantidade inicial/máxima, cor do destaque e área de clique */
  data: {
      name: "Gralha-azul",
      sci: "Cyanocorax caeruleus",
      diet: "Onívora",
      role: "Dispersora de araucárias",
      habitat: "Matas com araucária do Sul do Brasil.",
      desc: "Ave símbolo do Paraná. Enterra pinhões no chão e, ao esquecer alguns, ajuda a espalhar as araucárias.",
      fact: "É considerada a principal dispersora das sementes de araucária.",
      qty: 6,
      max: 24,
      color: "#7e57c2",
      hit: 0.7,
      hy: 0,
      top: 0.9,
      kind: "fly"
  },

  /* 2) ÍCONE (legenda e card) */
  icon: `<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M10 40l-6 4 14-4z" fill="#1a3a8f"/><ellipse cx="22" cy="29" rx="13" ry="11" fill="#2a56c7" transform="rotate(-15 22 29)"/><path d="M12 26c6-8 18-6 22 2-8-2-16-1-22-2z" fill="#1a3a8f"/><circle cx="31" cy="17" r="8" fill="#0f1a3d"/><path d="M26 10l2-8 5 8z" fill="#0f1a3d"/><path d="M37 16l8 3-8 2z" fill="#2b2b2b"/><circle cx="32" cy="15" r="1.8" fill="#fff"/><circle cx="32.4" cy="15" r=".9" fill="#000"/></svg>`,

  /* 3) MODELO 3D (malha realista + textura fotográfica; pernas finas como antes) */
  build(sp) {
    const { CY, M } = Kit, u = sp.top, g = new THREE.Group(), rig = new THREE.Group(); g.add(rig);
    const shared = gralhaShared();

    // corpo realista: cabeça em +x, dorso em +y (mesma convenção dos outros animais)
    const body = new THREE.Group(), s = u * 1.9;
    const mesh = new THREE.Mesh(shared.geo, shared.mat);
    mesh.scale.setScalar(s);
    mesh.position.y = -u * .2 - GRALHA_MESH.minY * s;   // barriga logo acima das pernas
    mesh.castShadow = true;
    body.add(mesh); rig.add(body);

    // pernas escuras (mesma posição de antes)
    CY(0x2a2a2e, u * .015, u * .2, u * .02, -u * .3, u * .06, 0, 0, rig);
    CY(0x2a2a2e, u * .015, u * .2, u * .02, -u * .3, -u * .06, 0, 0, rig);

    // asas: o sistema de animação continua recebendo seus pivôs (ficam invisíveis,
    // pois a asa do modelo realista é fechada). O "bater de asas" vira um balanço do corpo.
    const before = rig.children.length;
    const wings = Kit.wings(rig, u, 0x2a56c7);
    for (let i = before; i < rig.children.length; i++) rig.children[i].visible = false;
    mesh.onBeforeRender = () => {
      // O sistema move a asa em rotation.x: bate entre -0,7 e +0,7 voando e fica em +1,3 com a asa dobrada (pousado).
      const w = Array.isArray(wings) && wings[0], p = w && (Array.isArray(w) ? w[0] : w);
      let f = 0;
      if (p && p.rotation) { const v = p.rotation.x; f = v * (1 - Math.max(0, Math.min(1, (v - .75) / .5))); }   // só a batida; dobrada (pousado) = 0
      body.position.y = Math.abs(f) * u * .08;
      body.rotation.z = -f * .12;
    };

    g.userData = { wings, head: mesh, rig };
    return g;
  },

  /* 4) COMPORTAMENTO: pousa nas árvores, desce ao chão para bicar (enterrar pinhão) e voa. */
  decide(a, H) {
    const p = Math.random();
    if (p < .4) { const t = H.rt(); return H.go(a, H.V(t.x, t.top + .3, t.z), 'land', H.r(5, 10)); }
    if (p < .6) { const q = H.landPoint(); q.y = .3; return H.go(a, q, 'peck', H.r(4, 7)); }
    H.go(a, H.flyPoint('gralha'), 'fly', 0);
  }
});

/* Geometria e material compartilhados por todas as gralhas (criados uma única vez). */
let _gralhaShared = null;
function gralhaShared() {
  if (_gralhaShared) return _gralhaShared;
  const D = GRALHA_MESH, n = D.n;
  const bytes = b64 => { const s = atob(b64), a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a; };
  const i16 = new Int16Array(bytes(D.pos).buffer), i8 = new Int8Array(bytes(D.nrm).buffer),
        u16 = new Uint16Array(bytes(D.uv).buffer), idx = new Uint16Array(bytes(D.idx).buffer);
  const pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3), uv = new Float32Array(n * 2);
  for (let i = 0; i < n * 3; i++) { pos[i] = i16[i] / 65534; nrm[i] = i8[i] / 127; }
  for (let i = 0; i < n * 2; i++) uv[i] = u16[i] / 65535;
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
  geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  geo.setIndex(new THREE.BufferAttribute(idx, 1));
  geo.computeBoundingSphere();
  const tex = new THREE.TextureLoader().load(D.tex);
  tex.encoding = THREE.sRGBEncoding; tex.anisotropy = 4;
  const mat = new THREE.MeshStandardMaterial({ map: tex, roughness: .8, metalness: 0, side: THREE.DoubleSide });
  return (_gralhaShared = { geo, mat });
}
